//! Replays the pinned CesiumJS PointCloud capture in
//! `tests/data/scene-point-cloud.json` (generated by
//! `tools/cesium/generate-scene-point-cloud.mjs`): parsing, attribute layout,
//! buffer sizes, shader source and render state.
use base64::Engine;
use cesium_rs::core::*;
use cesium_rs::renderer::*;
use cesium_rs::scene::*;
use serde_json::Value;
use std::{cell::{Cell, RefCell}, rc::Rc, sync::Arc};

const MAX_TEXTURE_SIZE: f64 = 0xD33 as f64;
const MAX_COMBINED_TEXTURE_IMAGE_UNITS: f64 = 0x8B4D as f64;

#[derive(Clone, Default)]
struct Host {
    next: Rc<Cell<u32>>,
    buffers: Rc<RefCell<Vec<usize>>>,
}
impl Gl for Host {
    type Object = u32;
    fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
        Ok([64, 64])
    }
    fn invoke(&self, name: &str, args: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
        let number = |index: usize| match args.get(index) {
            Some(GlValue::Number(value)) => Some(*value),
            _ => None,
        };
        if name == "bufferData" {
            if let Some(GlValue::Bytes(bytes)) = args.get(1) {
                self.buffers.borrow_mut().push(bytes.len());
            }
        }
        Ok(if name.starts_with("create") {
            self.next.set(self.next.get() + 1);
            GlValue::Object(self.next.get())
        } else {
            match name {
                "getParameter" => match number(0) {
                    Some(value)
                        if value == 0x846D as f64
                            || value == 0x846E as f64
                            || value == 0xD3A as f64 =>
                    {
                        GlValue::Numbers(vec![1., 4096.])
                    }
                    Some(value) if value == MAX_TEXTURE_SIZE => GlValue::Number(4096.),
                    Some(value) if value == MAX_COMBINED_TEXTURE_IMAGE_UNITS => GlValue::Number(32.),
                    _ => GlValue::Number(4096.),
                },
                "getExtension" => GlValue::Object(0),
                "getShaderParameter" | "getProgramParameter" => GlValue::Bool(true),
                "checkFramebufferStatus" => GlValue::Number(36053.),
                _ => GlValue::Null,
            }
        })
    }
}

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-point-cloud.json")).unwrap()
}

#[test]
fn point_cloud_resources_and_shaders_match_pinned_cesium() {
    let uploads = Rc::new(RefCell::new(Vec::new()));
    let host = Host { next: Rc::new(Cell::new(0)), buffers: uploads.clone() };
    let context = Context::new_webgl2(host);
    for case in fixture()["cases"].as_array().unwrap() {
        let settings = &case["settings"];
        uploads.borrow_mut().clear();
        let bytes = base64::engine::general_purpose::STANDARD
            .decode(case["arrayBufferBase64"].as_str().unwrap())
            .unwrap();
        let mut cloud = PointCloud::<Host>::new(PointCloudOptions {
            array_buffer: Arc::new(bytes),
            byte_offset: 0,
            cull: true,
            opaque_pass: if settings["batchIds"].as_bool().unwrap() {
                Pass::Cesium3DTile
            } else {
                Pass::Opaque
            },
            split_direction: SplitDirection::None,
            callbacks: PointCloudCallbacks::default(),
        })
        .unwrap();
        cloud.attenuation = settings["attenuation"].as_bool().unwrap();
        cloud.back_face_culling = settings["backFaceCulling"].as_bool().unwrap();
        cloud.normal_shading = settings["normalShading"].as_bool().unwrap();
        cloud.geometric_error = 2.5;
        cloud.geometric_error_scale = 3.0;
        cloud.maximum_attenuation = 10.0;
        if !settings["style"].is_null() {
            let style = Cesium3DTileStyle::new(Some(&settings["style"])).unwrap();
            cloud.style = Some(Rc::new(RefCell::new(style)));
        }
        if settings["clipping"].as_u64().unwrap() > 0 {
            let mut planes = ClippingPlaneCollection::new([ClippingPlane::handle(
                Cartesian3::new(0.0, 0.0, 1.0),
                0.0,
            )]);
            planes.enabled = true;
            cloud.clipping_planes = Some(Rc::new(RefCell::new(planes)));
            cloud.is_clipped = true;
        }
        let mut camera = Camera::new(CameraOptions::new(64., 64.));
        camera.position = Cartesian3::new(0., 0., 10.);
        let uniform = camera.uniform_camera();
        let culling = CullingVolume::from_bounding_sphere(&BoundingSphere::new(Cartesian3::ZERO, 100.));
        let mut frame = FrameState::new(
            UniformFrame::new(uniform, JulianDate::new(2451545., 0., TimeStandard::Tai)),
            culling,
            [64, 64],
        );
        frame.context = Some(FrameResource::new(context.clone()));
        frame.mode = SceneMode::Scene3D;
        frame.pixel_ratio = 2.0;
        frame.drawing_buffer_height = 64;
        frame.passes.render = true;
        cloud.update(&mut frame).unwrap();

        assert_eq!(cloud.points_length(), case["pointsLength"].as_u64().unwrap() as usize);
        assert_eq!(cloud.geometry_byte_length(), case["geometryByteLength"].as_u64().unwrap() as usize);
        assert_eq!(cloud.ready(), case["ready"].as_bool().unwrap());
        assert_eq!(cloud.is_translucent(), case["isTranslucent"].as_bool().unwrap());
        assert_eq!(cloud.style_translucent(), case["styleTranslucent"].as_bool().unwrap());
        let command = cloud.draw_command().expect("draw command");
        assert_eq!(command.pass as u64, case["renderState"]["pass"].as_u64().unwrap());
        assert_eq!(command.metadata.cull, case["renderState"]["cull"].as_bool().unwrap());
        let state = cloud.render_state();
        assert_eq!(
            state.depth_test.enabled,
            case["renderState"]["depthTest"]["enabled"].as_bool().unwrap()
        );
        assert_eq!(state.depth_mask, case["renderState"]["depthMask"].as_bool().unwrap());
        assert_eq!(
            state.blending.enabled,
            case["renderState"]["blending"]["enabled"].as_bool().unwrap()
        );
        assert_eq!(
            state.blending.function_source_rgb,
            case["renderState"]["blending"]["functionSourceRgb"].as_u64().unwrap() as u32
        );
        assert_eq!(
            state.blending.function_destination_rgb,
            case["renderState"]["blending"]["functionDestinationRgb"].as_u64().unwrap() as u32
        );

        let actual_attributes: Vec<(u32, u32, u64, bool)> = cloud
            .vertex_array()
            .unwrap()
            .attributes()
            .iter()
            .map(|attribute| {
                (
                    attribute.index,
                    attribute.components,
                    attribute.datatype as u64,
                    attribute.normalize,
                )
            })
            .collect();
        let expected_attributes: Vec<(u32, u32, u64, bool)> = case["attributes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|attribute| {
                (
                    attribute["index"].as_u64().unwrap() as u32,
                    attribute["componentsPerAttribute"].as_u64().unwrap() as u32,
                    attribute["componentDatatype"].as_u64().unwrap(),
                    attribute["normalize"].as_bool().unwrap(),
                )
            })
            .collect();
        assert_eq!(actual_attributes, expected_attributes, "attributes for {settings}");

        let expected_buffers: Vec<usize> =
            case["buffers"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
        let actual_buffers: Vec<usize> = uploads.borrow().clone();
        assert_eq!(actual_buffers, expected_buffers, "buffer sizes for {settings}");

        let (vertex, fragment) = cloud.shader_source().expect("shader source");
        // Cesium concatenates most shader lines without indentation; compare
        // the exact token sequence and line content, ignoring leading spaces.
        let normalize = |source: &str| -> Vec<String> {
            source.lines().map(|line| line.trim_start().to_string()).collect()
        };
        assert_eq!(
            normalize(vertex),
            normalize(case["shader"]["vertex"].as_str().unwrap()),
            "vertex shader for {settings}"
        );
        assert_eq!(
            normalize(fragment),
            normalize(case["shader"]["fragment"].as_str().unwrap()),
            "fragment shader for {settings}"
        );
        let mut actual_uniforms: Vec<String> = cloud.uniform_names().to_vec();
        actual_uniforms.sort();
        let expected_uniforms: Vec<String> = case["uniformNames"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().into())
            .collect();
        assert_eq!(actual_uniforms, expected_uniforms, "uniform names for {settings}");
        cloud.destroy().unwrap();
    }
}

fn minimal_pnts(rtc_center: Option<[f64; 3]>) -> Vec<u8> {
    let mut ft_json = serde_json::json!({
        "POINTS_LENGTH": 1,
        "POSITION": { "byteOffset": 0 }
    });
    if let Some(rtc) = rtc_center {
        ft_json["RTC_CENTER"] = serde_json::json!(rtc);
    }
    let mut json_bytes = serde_json::to_vec(&ft_json).unwrap();
    while !(28 + json_bytes.len()).is_multiple_of(8) {
        json_bytes.push(b' ');
    }
    let mut bin_bytes = Vec::new();
    for coord in [1.0f32, 2.0, 3.0] {
        bin_bytes.extend_from_slice(&coord.to_le_bytes());
    }
    while !bin_bytes.len().is_multiple_of(8) {
        bin_bytes.push(0);
    }
    let total_len = (28 + json_bytes.len() + bin_bytes.len()) as u32;
    let mut out = Vec::with_capacity(total_len as usize);
    out.extend_from_slice(b"pnts");
    out.extend_from_slice(&1u32.to_le_bytes());
    out.extend_from_slice(&total_len.to_le_bytes());
    out.extend_from_slice(&(json_bytes.len() as u32).to_le_bytes());
    out.extend_from_slice(&(bin_bytes.len() as u32).to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes());
    out.extend_from_slice(&json_bytes);
    out.extend_from_slice(&bin_bytes);
    out
}

#[test]
fn rtc_center_offset_does_not_drift_across_updates() {
    let context = Context::new_webgl2(Host::default());
    let bytes = minimal_pnts(Some([10.0, 20.0, 30.0]));
    let mut cloud = PointCloud::<Host>::new(PointCloudOptions {
        array_buffer: Arc::new(bytes),
        ..Default::default()
    })
    .unwrap();
    let base_matrix = Matrix4::from_translation(Cartesian3::new(100.0, 200.0, 300.0));
    cloud.model_matrix = base_matrix;

    let mut camera = Camera::new(CameraOptions::new(64., 64.));
    camera.position = Cartesian3::new(0., 0., 10.);
    let uniform = camera.uniform_camera();
    let culling = CullingVolume::from_bounding_sphere(&BoundingSphere::new(Cartesian3::ZERO, 100.));
    let mut frame = FrameState::new(
        UniformFrame::new(uniform, JulianDate::new(2451545., 0., TimeStandard::Tai)),
        culling,
        [64, 64],
    );
    frame.context = Some(FrameResource::new(context));
    frame.passes.render = true;

    cloud.update(&mut frame).unwrap();
    let expected = base_matrix.multiply_by_translation(Cartesian3::new(10.0, 20.0, 30.0));
    assert_eq!(cloud.model_matrix, base_matrix);
    assert_eq!(cloud.computed_model_matrix(), expected);
    assert_eq!(cloud.draw_command().unwrap().metadata.model_matrix, Some(expected));
    let first_sphere = cloud.bounding_sphere().unwrap();

    // Repeated updates without changing model_matrix must not re-apply RTC_CENTER.
    cloud.update(&mut frame).unwrap();
    cloud.update(&mut frame).unwrap();
    assert_eq!(cloud.model_matrix, base_matrix);
    assert_eq!(cloud.computed_model_matrix(), expected);
    assert_eq!(cloud.draw_command().unwrap().metadata.model_matrix, Some(expected));
    assert_eq!(cloud.bounding_sphere().unwrap(), first_sphere);
    cloud.destroy().unwrap();
}

#[test]
fn highlight_alpha_change_updates_executed_render_state() {
    type CallLog = Rc<RefCell<Vec<(String, Vec<f64>)>>>;
    #[derive(Clone, Default)]
    struct StateRecordingGl {
        next: Rc<Cell<u32>>,
        calls: CallLog,
    }
    impl Gl for StateRecordingGl {
        type Object = u32;
        fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
            Ok([64, 64])
        }
        fn invoke(&self, name: &str, args: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
            let nums: Vec<f64> = args
                .iter()
                .filter_map(|arg| match arg {
                    GlValue::Number(v) => Some(*v),
                    GlValue::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
                    _ => None,
                })
                .collect();
            self.calls.borrow_mut().push((name.to_string(), nums));
            Ok(if name.starts_with("create") {
                self.next.set(self.next.get() + 1);
                GlValue::Object(self.next.get())
            } else {
                match name {
                    "getParameter" => match args.first() {
                        Some(GlValue::Number(v)) if *v == 0x846D as f64 || *v == 0x846E as f64 || *v == 0xD3A as f64 => {
                            GlValue::Numbers(vec![1., 4096.])
                        }
                        _ => GlValue::Number(4096.),
                    },
                    "getExtension" => GlValue::Object(0),
                    "getShaderParameter" | "getProgramParameter" => GlValue::Bool(true),
                    "checkFramebufferStatus" => GlValue::Number(36053.),
                    _ => GlValue::Null,
                }
            })
        }
    }

    let gl = StateRecordingGl::default();
    let context = Context::new_webgl2(gl.clone());
    let mut cloud = PointCloud::<StateRecordingGl>::new(PointCloudOptions {
        array_buffer: Arc::new(minimal_pnts(None)),
        ..Default::default()
    })
    .unwrap();

    let mut camera = Camera::new(CameraOptions::new(64., 64.));
    camera.position = Cartesian3::new(0., 0., 10.);
    let uniform = camera.uniform_camera();
    let culling = CullingVolume::from_bounding_sphere(&BoundingSphere::new(Cartesian3::ZERO, 100.));
    let mut frame = FrameState::new(
        UniformFrame::new(uniform, JulianDate::new(2451545., 0., TimeStandard::Tai)),
        culling,
        [64, 64],
    );
    frame.context = Some(FrameResource::new(context));
    frame.passes.render = true;

    cloud.update(&mut frame).unwrap();
    assert_eq!(cloud.draw_command().unwrap().pass, Pass::Opaque);

    // Switching highlight alpha below 1.0 without rebuilding shaders must update both
    // the command pass and its executed GL render state (blending on, depthMask false).
    cloud.set_color(Color::new(1.0, 1.0, 1.0, 0.5));
    cloud.update(&mut frame).unwrap();
    let command = cloud.draw_command().unwrap().clone();
    assert_eq!(command.pass, Pass::Translucent);
    gl.calls.borrow_mut().clear();
    let submission = SceneSubmission {
        pass: command.pass,
        frustum: 0,
        near: 0.1,
        far: 1000.0,
        draw_mode: SceneDrawMode::default(),
        oit: None,
        metadata_pick: None,
        framebuffer: None,
        viewport: None,
        scissor_test: None,
        blending_enabled: None,
        metadata: command.metadata.clone(),
        clipping_planes: None,
        tileset_draw: None,
    };
    (command.execute)(submission).unwrap();
    let calls = gl.calls.borrow();
    assert!(calls.iter().any(|(name, args)| name == "enable" && args.first() == Some(&(0x0BE2 as f64))));
    assert!(calls.iter().any(|(name, args)| name == "depthMask" && args.first() == Some(&0.0)));
    cloud.destroy().unwrap();
}
